import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC01%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E5%8C%96%E5%8F%91%E5%B1%95/1.3%20%E7%8E%B0%E4%BB%A3%E5%8C%96%E5%88%9B%E6%96%B0%E5%8F%91%E5%B1%95.html","title":"1.3 现代化创新发展","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第01章 信息化发展/1.3 现代化创新发展.md"}`),a={name:`1.3 现代化创新发展.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_1-3-现代化创新发展" tabindex="-1"><a class="header-anchor" href="#_1-3-现代化创新发展"><span>1.3 现代化创新发展</span></a></h1><h2 id="_1-3-1-农业农村现代化" tabindex="-1"><a class="header-anchor" href="#_1-3-1-农业农村现代化"><span>1.3.1 农业农村现代化</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>是用现代工业装备农业，用现代科学技术改造农业，用现代管理方法管理农业，用现代科学文化知识提高农民素质的过程；农业信息化是农业现代化的重要技术手段</p><h3 id="乡村振兴战略" tabindex="-1"><a class="header-anchor" href="#乡村振兴战略"><span>乡村振兴战略</span></a></h3><ol><li><strong>建设基础设施</strong></li></ol><p>一手抓新建、一手抓改造，提出推动农村千兆光网、5G、移动物联网与城市同步规划建设，提升农村宽带网络水平，推动农业生产加工和农村基础设施数字化、智能化升级</p><ol start="2"><li><strong>发展智慧农业</strong></li></ol><p>建立和推广应用农业农村大数据体系，推动物联网、大数据、人工智能、区块链等新一代信息技术与农业生产经营深度融合，建设一批数字田园、数字灌区和智慧农牧渔场，不断提高农业发展数字化水平</p><ol start="3"><li><strong>建设数字乡村</strong></li></ol><p>构建线上线下相结合的乡村数字惠民便民服务体系，推进互联网+政务服务向农村基层延伸，深化乡村智慧社区建设，促进农村教育、医疗、文化与数字化结合，提升乡村治理和服务的智能化、精准化水平</p><h2 id="_1-3-2-两化融合与智能制造" tabindex="-1"><a class="header-anchor" href="#_1-3-2-两化融合与智能制造"><span>1.3.2 两化融合与智能制造</span></a></h2><h3 id="两化融合" tabindex="-1"><a class="header-anchor" href="#两化融合"><span>两化融合</span></a></h3><ol><li><p>两化融合是信息化和工业化的高层次的深度结合，是指以信息化带动工业化、以工业化促进信息化，走新型工业化道路</p></li><li><p>两化融合的核心就是信息化支撑，追求可持续发展模式</p></li><li><p>信息化与工业化主要在<strong>技术、产品、业务、产业</strong>四个方面进行融合</p></li></ol><p>记忆：【极品物业】</p><ol><li><strong>技术融合</strong>：工业技术与信息技术的融合，产生新的技术，推动技术创新</li><li><strong>产品融合</strong>：电子信息技术产品渗透到产品中，增加产品的技术含量</li><li><strong>业务融合</strong>：信息技术应用到企业研发设计、生产制造、经营管理、市场营销等各个环节，推动企业业务创新和管理升级</li><li><strong>产业衍生</strong>：两化融合可以催生出的新产业，形成一些新兴业态</li></ol><h3 id="智能制造" tabindex="-1"><a class="header-anchor" href="#智能制造"><span>智能制造</span></a></h3><h4 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h4><ol><li><p>智能制造是基于新一代信息通信技术与先进制造技术深度融合，贯穿于设计、生产、管理、服务等制造活动的各个环节，具有自感知、自学习、自决策、自执行、自适应等功能的新型生产方式</p></li><li><p>智能制造是一种由智能机器和人类专家共同组成的人机一体化智能系统，它在制造过程中能进行智能活动，诸如分析、推理、判断、构思和决策</p></li></ol><h4 id="能力要素" tabindex="-1"><a class="header-anchor" href="#能力要素"><span>能力要素</span></a></h4><ul><li><strong>人员</strong>——组织战略、人员技能 记忆：组人</li><li><strong>技术</strong>——数据、集成、信息安全 记忆：技术成全</li><li><strong>资源</strong>——装备、网络 记忆：原装网</li><li><strong>制造</strong>——设计、生产、物流、销售、服务</li></ul><h4 id="能力等级" tabindex="-1"><a class="header-anchor" href="#能力等级"><span>能力等级</span></a></h4><ol><li><strong>一级（规划级）</strong></li></ol><p>企业应开始对实施智能制造的基础和条件进行规划，能够对核心业务活动进行流程化管理</p><ol start="2"><li><strong>二级（规范级）</strong></li></ol><p>企业应采用自动化技术、信息技术手段对核心装备和业务活动等进行改造和规范，实现单一业务活动的数据共享</p><ol start="3"><li><strong>三级（集成级）</strong></li></ol><p>企业应对装备、系统等开展集成，实现跨业务活动间的数据共享</p><ol start="4"><li><strong>四级（优化级）</strong></li></ol><p>企业应对人员、资源、制造等进行数据挖掘，形成知识、模型等，实现对核心业务活动的精准预测和优化</p><ol start="5"><li><strong>五级（引领级）</strong></li></ol><p>企业应基于模型持续驱动业务活动的优化和创新，实现产业链协同并衍生新的制造模式和商业模式</p><h2 id="_1-3-3-消费互联网" tabindex="-1"><a class="header-anchor" href="#_1-3-3-消费互联网"><span>1.3.3 消费互联网</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>以个人为用户，以日常生活为应用场景的应用形式，满足消费者在互联网中的消费需求而生的互联网类型</p><h3 id="属性" tabindex="-1"><a class="header-anchor" href="#属性"><span>属性</span></a></h3><ol><li><p><strong>媒体属性</strong>：以消费者为服务中心，针对个人用户提升消费过程的体验，在人们的阅读、出行、娱乐、生活等诸多方面进行改善，让生活变得更方便、更快捷。消费互联网本质是个人虚拟化，增强个人生活消费体验；自由媒体、社会媒体、资讯为主的门户网站</p></li><li><p><strong>产业属性</strong>：由在线旅行和为消费者提供生活服务的电子商务等其他组成</p></li></ol><h3 id="应用新格局" tabindex="-1"><a class="header-anchor" href="#应用新格局"><span>应用新格局</span></a></h3><ol><li><p>消费互联网不仅仅给人们带来了生活方式的变化和生活质量的提高，而且推动了社会生活的深层变革，那就是<strong>无身份社会</strong>的建立</p></li><li><p>互联网环境下的无身份社会带来了更加快捷的社会活动与经济效益。相关参与者可以不用消耗时间精力来完成共同参与者的身份认定，这是因为互联网搭建了更高层级的信任校验模式，其通过数据记录、存储、整合与共享等方面的能力，实现了社会活动的一定程度上的复杂校验和过程可回溯，进一步强化了无身份社会的发展进程</p></li><li><p>加快发展线下向&quot;上&quot;融合和线上向下&quot;拓展的双向消费形态</p></li></ol>`,39)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};